<script setup lang="ts">
import {onMounted,ref} from 'vue'
type Report={format:string;version:number;created:string;release:string;os:string;architecture:string;goVersion:string;wailsVersion:string;configurationHealth:string;historyHealth:string;storageSummary:string;monitorCount:number;states:Record<string,number>;checks:Record<string,number>;openIncidents:number;pendingDeliveries:number;probeConcurrency:number;historyQueueLength:number;historyQueueCapacity:number}
const api=()=> (window as unknown as {go?:{main:{App:{GetSupportReport:()=>Promise<Report>;ExportSupportReport:()=>Promise<string>}}}}).go?.main.App
const report=ref<Report|null>(null),busy=ref(false),error=ref(''),saved=ref('')
async function refresh(){if(!api())return;busy.value=true;error.value='';try{report.value=await api()!.GetSupportReport()}catch{error.value='Support information could not be loaded. Try refreshing.'}finally{busy.value=false}}
async function exportReport(){busy.value=true;error.value='';saved.value='';try{saved.value=await api()!.ExportSupportReport()}catch{error.value='Diagnostics could not be saved. Try a writable location outside Hostlight’s settings and history files.'}finally{busy.value=false}}
onMounted(refresh)
</script>
<template>
 <section class="support-info"><h2>Support information</h2><p>Checks and alerts run while Hostlight is running, including when hidden to tray. This snapshot helps troubleshoot storage, monitoring, and delivery queues.</p><div class="support-actions"><button :disabled="busy||!api()" @click="refresh">Refresh snapshot</button><button class="primary" :disabled="busy||!report" @click="exportReport">Export sanitized diagnostics</button></div><p v-if="!api()">Open Hostlight through Wails to load support information.</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="saved" role="status">Diagnostics saved to {{saved}}. Review the file before sharing it.</p>
 <dl v-if="report"><dt>Release</dt><dd>{{report.release}}</dd><dt>Platform</dt><dd>{{report.os}} / {{report.architecture}}</dd><dt>Runtime</dt><dd>{{report.goVersion}} · Wails {{report.wailsVersion}}</dd><dt>Configuration</dt><dd>{{report.configurationHealth}}</dd><dt>Incident storage</dt><dd>{{report.historyHealth}}</dd><dt>Monitors</dt><dd>{{report.monitorCount}}</dd><dt>States</dt><dd><span v-for="(count,state) in report.states" :key="state">{{state}}: {{count}} · </span></dd><dt>Checks</dt><dd><span v-for="(count,type) in report.checks" :key="type">{{type}}: {{count}} · </span></dd><dt>Open incidents</dt><dd>{{report.storageSummary==='ready'?report.openIncidents:'Unavailable'}}</dd><dt>Pending webhook deliveries</dt><dd>{{report.storageSummary==='ready'?report.pendingDeliveries:'Unavailable'}}</dd><dt>Maximum simultaneous checks</dt><dd>{{report.probeConcurrency}}</dd><dt>History queue</dt><dd>{{report.historyQueueLength}} / {{report.historyQueueCapacity}}</dd><dt>Snapshot time</dt><dd>{{new Date(report.created).toLocaleString()}}</dd></dl>
 <div class="notice"><strong>What is included?</strong><p>Platform/runtime versions, component health, aggregate monitor/check counts, open-incident and pending-delivery counts, and queue size. Counts may change while this snapshot is collected.</p><strong>What is excluded?</strong><p>Monitor names, hostnames/IPs, URLs, group names, paths/usernames, check messages, response bodies, incident details, webhook destinations, credentials, raw logs, and saved views. Nothing is uploaded automatically.</p></div>
 </section>
</template>
<style scoped>
.support-info{max-width:950px}.support-actions{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.support-info dl{display:grid;grid-template-columns:minmax(160px,1fr) 2fr;border:1px solid var(--border);border-radius:10px;padding:20px;background:var(--panel);gap:16px}.support-info dt{color:var(--muted)}.support-info dd{margin:0;overflow-wrap:anywhere}.support-info p{overflow-wrap:anywhere}
</style>
